#include<bits/stdc++.h>

using namespace std;

long long greedy(long long x,long long k,long long p,vector<long long> &a){
  if(x==0){return 0;}
  if(x<0){return 8e18;}
  long long res=0;
  for(long long i=p;i>=0;i--){
    long long use=(x/a[i]);
    res+=use;
    x-=use*a[i];
  }
  if(x>0){return 8e18;}
  return res;
}

int main(){
  int tc;
  cin >> tc;
  while(tc>0){
    tc--;
    long long d,k,x;
    cin >> d >> k >> x;

    long long res=8e18;
    vector<long long> a(d+1);
    a[0]=1;
    for(long long i=1;i<=d;i++){a[i]=a[i-1]*k+1;}

    for(long long h=d;h>=0;h--){
      long long rem=a[h]-x;
      if(0<=rem){
        long long up=1;
        if(h==d){up=0;}
        res=min(res,up+greedy(rem,k,h-1,a));
      }
    }
    cout << res << "\n";
  }
  return 0;
}
